// `space.4`/`.6`/`.8` — the exact values `PageContainer`/`layerStyle="page"` themselves apply —
// written out directly since neither has a `var(--zimm-*)` equivalent to reference.
export const PAGE_CONTENT_BLEED_MX = {
  base: 'calc((var(--zimm-grid-margin-mobile) + 1rem) * -1)', // 32+16=48px
