// index.tsx` was wrongly given `mx={PAGE_CONTENT_BLEED_MX}` above — that constant cancels TWO
// stacked layers (`#app-main`'s own padding + PDP/PLP's `PageContainer`/`layerStyle="page"` second
// layer), but the Full History page has no second layer at all (confirmed directly: no
// `PageContainer`, no `layerStyle`, nothing between `#app-main` and this page's own content).
// Cancelling 72px/56px/48px of margin against only 40px/32px/32px of real padding over-cancels by
// exactly the (nonexistent) second layer's own amount at every breakpoint, pushing the page that
// far past the true viewport edge on each side — confirmed against the reported screenshots' own
// numbers (e.g. Desktop: div rendered 1504px wide at a 1440px viewport, margin -72px each side;
// -40px would have landed it at exactly 1440px).
//
// This constant cancels ONLY `#app-main`'s own sitewide padding — the one layer that is genuinely
// universal to every page — so it needs just the two real `gridSystem.ts` breakpoints (`#app-main`
// itself has no intermediate step at 768px, unlike PAGE_CONTENT_BLEED_MX's own second layer, which
// is exactly why that constant needed a third `md` key and this one doesn't).
export const APP_MAIN_BLEED_MX = {
  base: 'calc(var(--zimm-grid-margin-mobile) * -1)', // 32px
  xl: 'calc(var(--zimm-grid-margin-desktop) * -1)', // 40px
} as const;

