import { describe, test, expect } from 'vitest';
import { ZimmRecentlyViewedGrid } from './zimmRecentlyViewedGrid.css';

/**
 * `index.test.tsx` mocks `useMultiStyleConfig` globally, so this recipe's own object shape is
 * never exercised by any shipped component test — these assertions are the only thing that
 * actually reads it. Guards against the exact regression found 2026-09-10: bare `1fr` columns
 * (shorthand for `minmax(auto, 1fr)`) let a hover-revealed child's own non-shrinking min-content
 * width (the size-chip row, once its spacing became a fixed `gap` rather than a stretchy
 * `justifyContent`) force a grid TRACK wider than its fair share at narrow column widths —
 * widening every card sharing that column, not just the hovered one, with the card's own
 * aspect-ratio-locked image growing as a downstream effect. `minmax(0, 1fr)` pins each track's
 * floor to zero regardless of what a child demands.
 */
describe('ZimmRecentlyViewedGrid — recipe wiring', () => {
  test('every declared part is produced by baseStyle', () => {
    const parts = Object.keys(ZimmRecentlyViewedGrid.baseStyle());
    expect(parts.sort()).toEqual([...ZimmRecentlyViewedGrid.parts].sort());
  });

  test('grid columns are minmax(0, 1fr) at every breakpoint, not bare 1fr', () => {
    const { grid } = ZimmRecentlyViewedGrid.baseStyle() as Record<string, Record<string, unknown>>;

    expect(grid.gridTemplateColumns).toContain('minmax(0,');
    expect(grid.gridTemplateColumns).not.toMatch(/repeat\(\d+, 1fr\)/);

    const breakpointKeys = Object.keys(grid).filter((key) => key.startsWith('@media'));
    expect(breakpointKeys.length).toBeGreaterThan(0);
    breakpointKeys.forEach((key) => {
      const breakpointStyles = grid[key] as Record<string, unknown>;
      if (breakpointStyles.gridTemplateColumns) {
        expect(breakpointStyles.gridTemplateColumns).toContain('minmax(0,');
        expect(breakpointStyles.gridTemplateColumns).not.toMatch(/repeat\(\d+, 1fr\)/);
      }
    });
  });
});

